#!/usr/bin/env bash\n# Tests for scan_todo.sh\n\nset -e\n\nSCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/../src" && pwd)"\nSCAN_SCRIPT="$SCRIPT_DIR/scan_todo.sh"\n\n# Test 1: Detect TODO\ntmpdir=$(mktemp -d)\ncat > "$tmpdir/file_with_todo.txt" <<'EOF'\n# This is a sample file\n# TODO: fix this later\nEOF\npushd "$tmpdir" > /dev/null\nexit_code=$(bash "$SCAN_SCRIPT"; echo $?)\nif [ "$exit_code" -ne 1 ]; then\n  echo "Test 1 failed: expected exit code 1, got $exit_code"\n  exit 1\nfi\npopd > /dev/null\nrm -rf "$tmpdir"\n\n# Test 2: No TODO\ntmpdir=$(mktemp -d)\ncat > "$tmpdir/clean_file.txt" <<'EOF'\nJust some clean content.\nEOF\npushd "$tmpdir" > /dev/null\nexit_code=$(bash "$SCAN_SCRIPT"; echo $?)\nif [ "$exit_code" -ne 0 ]; then\n  echo "Test 2 failed: expected exit code 0, got $exit_code"\n  exit 1\nfi\npopd > /dev/null\nrm -rf "$tmpdir"\n\necho "All tests passed."
